// One item per Notion board so a single credentialed HTTP node queries all
// three. Not a Merge - n8n Merge v3 silently drops input ports past idx 1.
const DBS = [
  { db_id: 'YOUR_NOTION_DB_MAIN', board: 'Jobs' },
  { db_id: 'YOUR_NOTION_DB_CLOUD', board: 'Cloud Networking' },
  { db_id: 'YOUR_NOTION_DB_SECURITY', board: 'Network Security' },
];
return DBS.map(d => ({ json: d }));

// Flatten the three board queries and take one page per poll. An interview
// sheet is a single Claude call plus three Google API calls, so one at a time
// keeps well clear of Notion's ~3 req/s limit.
const pages = [];
for (const item of $input.all()) {
  const r = item.json.results;
  if (Array.isArray(r)) pages.push(...r);
}
if (!pages.length) return [];

const state = $getWorkflowStaticData('global');
const now = Date.now();
const STALE_MS = 30 * 60 * 1000;

const locks = state.prepping || {};
for (const [pid, ts] of Object.entries(locks)) {
  if (now - ts > STALE_MS) delete locks[pid];
}

const page = pages.find(p => !locks[p.id]);
if (!page) { state.prepping = locks; return []; }

locks[page.id] = now;
state.prepping = locks;
return [{ json: page }];

// Gather everything the prep sheet needs: the job description from the page
// body, plus the analysis columns the scorer already wrote. Missing Skills is
// the valuable one - those are the gaps he will actually be probed on.
const page   = $('Pick One Interview').first().json;
const props  = page.properties || {};
const blocks = $json.results || [];

const rt  = p => (p && p.rich_text && p.rich_text[0] && p.rich_text[0].text
                    ? p.rich_text[0].text.content : '').trim();
const sel = p => (p && p.select ? p.select.name : '') || '';

const title   = (props['Job Title'] && props['Job Title'].title
                 && props['Job Title'].title[0] && props['Job Title'].title[0].text
                 ? props['Job Title'].title[0].text.content : 'Unknown Role').trim();
const company = rt(props['Company']) || 'Unknown Company';

// Prefer the text under the "Full Job Description" heading; fall back to all
// prose on the page, because rows created by the old apply-url path never got
// that heading written.
const under = [];
const all   = [];
let inDesc = false;
for (const b of blocks) {
  const t = b.type;
  if (t === 'heading_2') {
    const h = (b.heading_2.rich_text[0] || {}).plain_text || '';
    if (/Full Job Description/i.test(h)) { inDesc = true; continue; }
    if (inDesc) break;            // next heading ends the description
  }
  if (t === 'divider' && inDesc) break;
  const rich = b[t] && b[t].rich_text;
  if (Array.isArray(rich) && rich.length) {
    const s = rich.map(x => x.plain_text || '').join('').trim();
    if (!s) continue;
    all.push(s);
    if (inDesc) under.push(s);
  }
}
const description = (under.length ? under : all).join('\n').substring(0, 6000);

const folderUrl = (props['Drive Folder'] && props['Drive Folder'].url) || '';
const m = folderUrl.match(/folders\/([A-Za-z0-9_-]+)/);

const safe = (s, n) => (s || '').replace(/[^\w\s-]/g, '').replace(/\s+/g, ' ').trim().substring(0, n);

return [{ json: {
  page_id:   page.id,
  page_url:  page.url || '',
  title, company,
  score:     (props['Score'] && props['Score'].number) || null,
  role_type: sel(props['Role Type']),
  location:  rt(props['Location']),
  salary_min: (props['Salary Min'] && props['Salary Min'].number) || null,
  salary_max: (props['Salary Max'] && props['Salary Max'].number) || null,
  apply_url: (props['Apply URL'] && props['Apply URL'].url) || '',
  tags:      (props['Tags'] && props['Tags'].multi_select || []).map(t => t.name),
  fit_summary:    rt(props['Fit Summary']),
  missing_skills: rt(props['Missing Skills']),
  red_flags:      rt(props['Red Flags']),
  description,
  have_description: description.length >= 200,
  // No Drive Folder means documents were never generated for this job (he
  // jumped straight to Interviewing). Fall back to the applications root so
  // the sheet still lands somewhere sane instead of failing the Drive move.
  folder_id: m ? m[1] : 'YOUR_DRIVE_FOLDER_ID',
  folder_is_fallback: !m,
  folder_url: folderUrl,
  doc_title: `Interview Prep - ${safe(title, 45)} - ${safe(company, 25)} ${new Date().toISOString().split('T')[0]}`,
}}];

// Builds the interview-prep prompt.
//
// The CANDIDATE PROFILE block below is NOT written here - build_interview.py
// lifts it out of scorer_src/build_score_prompt.js at deploy time and splices
// it in where the placeholder sits. That keeps one source of truth for the
// profile instead of a third copy drifting away from the other two.
const d = $('Extract Interview Context').first().json;

const CANDIDATE_PROFILE = `CANDIDATE PROFILE — Your Name
- Location: Remote strongly preferred. Hybrid/onsite acceptable ONLY in Your City or the Metro Area (Nearby City A/B/C), ST. Remote-Only City counts ONLY if the role is remote. Onsite/hybrid anywhere else, or relocation, is a dealbreaker. Max 10% travel.
- Experience: [N] years in [networking / security / infrastructure] — NOT a software developer
- Current Role: [Title], [Employer] ([year]–present)
  • [Scope: number of sites, users, devices]
  • [Key platform or responsibility]
  • [Current project]

- STRONG / EXPERT skills:
  • Routing: [e.g. BGP, OSPF, MPLS]
  • Switching: [e.g. VLANs, QoS, vendor platforms]
  • Wireless: [platforms]
  • Firewalls: [vendors — config, rule lifecycle, hardening]
  • Monitoring: [e.g. Prometheus, Grafana, SolarWinds]
  • Systems: [OSes, hypervisors, containers]
  • Automation: [tools — and how deep]
  • Vendors: [list]

- LIMITED / DEVELOPING:
  • [Skill]: [honest depth — conceptual only / end-user / in training]
  • [Skill]: [honest depth]

- Certifications: [certs and degrees]
- Salary: target ~$[N]k — a posted range that reaches $[N]k at either end is on target. More is welcome.
- Hard dealbreakers: [e.g. onsite outside your area, relocation, clearance, drug testing, travel >10%]
- Employer size: [preference, e.g. prefers organizations under 10,000 employees — soft flag]`;

const money = n => (typeof n === 'number' ? '$' + n.toLocaleString() : null);
const sal = d.salary_min || d.salary_max
  ? [money(d.salary_min), money(d.salary_max)].filter(Boolean).join(' - ')
  : 'not stated';

const analysis = [
  d.fit_summary    ? `Fit summary (from the automated scoring): ${d.fit_summary}` : null,
  d.missing_skills && d.missing_skills !== 'None'
    ? `Skills the scorer flagged as MISSING from his background: ${d.missing_skills}` : null,
  d.red_flags && d.red_flags !== 'None'
    ? `Concerns the scorer raised about this role: ${d.red_flags}` : null,
  d.tags && d.tags.length ? `Technologies tagged on this posting: ${d.tags.join(', ')}` : null,
].filter(Boolean).join('\n');

const jd = d.have_description
  ? d.description
  : 'No job description is stored for this posting. Build the sheet from the title, company and tagged technologies alone, and say so at the top of role_snapshot.';

const prompt = `You are an interview coach preparing a senior network/infrastructure engineer for a specific interview. Produce a focused prep sheet.

${CANDIDATE_PROFILE}

THE INTERVIEW:
Role: ${d.title}
Company: ${d.company}
Role type: ${d.role_type || 'unspecified'}
Location: ${d.location || 'unspecified'}
Posted salary: ${sal}

WHAT THE AUTOMATED SCORING ALREADY FOUND:
${analysis || '(no prior analysis on file)'}

JOB DESCRIPTION:
${jd}

TASK: Write a practical prep sheet. Focus on the TECHNOLOGIES AND SKILLS THIS
JOB ACTUALLY REQUIRES, and separately on the "nice to have" / "preferred" /
"bonus" items the posting mentions — those are where interviews are won or
lost, and where he most needs a prepared answer.

Rules:
- Draw every question from THIS posting. No generic "tell me about yourself".
- For each question, say which of HIS REAL experiences to reach for. Use only
  things in the candidate profile above. Never invent experience.
- Where a required skill is one of his gaps, say plainly how to answer
  honestly without overclaiming — what he HAS done that is adjacent, and what
  he is actively learning. Do not coach him to bluff.
- Keep each field tight. This is a one-page sheet he reads before a call, not
  an essay.

Return ONLY valid JSON — no markdown fences, no extra text:
{
  "role_snapshot": "Two sentences: what this role actually is day to day, and the single thing they most want to verify he can do.",
  "required_tech": [
    {
      "question": "A question they are likely to ask about a REQUIRED technology or skill",
      "why": "One short line on why this comes up for this role",
      "answer_with": "Which specific experience of his to lead with, and the concrete detail or metric to cite"
    }
  ],
  "nice_to_haves": [
    {
      "question": "A question about a 'preferred' / 'nice to have' / 'bonus' item in the posting",
      "why": "One short line",
      "answer_with": "What he has that is closest, framed honestly"
    }
  ],
  "gap_questions": [
    {
      "question": "A question about something the posting requires that he genuinely lacks",
      "why": "One short line naming the gap",
      "answer_with": "An honest answer: the adjacent thing he HAS done, plus what he is actively learning. No bluffing."
    }
  ],
  "ask_them": [
    "A sharp question for HIM to ask the interviewer, specific to this company or role"
  ]
}

Counts: exactly 5 required_tech, 3 nice_to_haves, 2 gap_questions, 4 ask_them.
If the posting genuinely lists no preferred/bonus items, still produce 3
nice_to_haves drawn from secondary skills the description implies, and say so
in the "why" line.`;

// Pre-built so the HTTP node carries no inline expression - an n8n expression
// containing an adjacent "}}" terminates early and fails with "invalid syntax".
const claude_body = JSON.stringify({
  model: 'claude-sonnet-4-6',
  max_tokens: 4000,
  messages: [{ role: 'user', content: prompt }],
});

return [{ json: { ...d, claude_body } }];

// Render Claude's prep sheet into a formatted Google Doc batchUpdate body.
// Same index-tracking approach as the docs branch's Parse Docs: text is
// accumulated while character offsets are recorded, then style requests are
// appended referencing those ranges.
const resp = $input.first().json;
const d    = $('Build Interview Prompt').first().json;

const raw = (resp.content && resp.content[0] && resp.content[0].text) || '';
let r = null;
try {
  const BT = String.fromCharCode(96);
  let c = raw.replace(new RegExp(BT + BT + BT + '(json)?', 'g'), '').trim();
  const s = c.indexOf('{'), e = c.lastIndexOf('}');
  if (s >= 0 && e > s) c = c.substring(s, e + 1);
  r = JSON.parse(c);
} catch (err) { r = null; }

if (!r || !Array.isArray(r.required_tech)) {
  // Fail loudly in Notion rather than leaving a blank doc behind. Status is
  // untouched: the row stays "Interviewing" but Interview Prep gets no URL,
  // so the next poll retries once the lock releases.
  return [{ json: {
    page_id: d.page_id, ok: false,
    discord_msg: ':warning: **Interview prep failed** for **' + d.title +
                 '** @ ' + d.company + ' - Claude returned no usable JSON.\n' +
                 (d.page_url || ''),
  }}];
}

const DARK_BLUE = { color: { rgbColor: { red: 0.110, green: 0.239, blue: 0.376 } } };
const MED_GRAY  = { color: { rgbColor: { red: 0.40, green: 0.40, blue: 0.40 } } };

let text = '';
let pos = 1;
const fmt = [];

function add(t, style, align) {
  if (!t) return;
  const start = pos;
  text += t; pos += t.length;
  const end = pos;
  if (style) {
    let se = end;
    for (let i = t.length - 1; i >= 0 && t[i] === '\n'; i--) se--;
    if (se > start) {
      const ts = {}, f = [];
      if (style.bold     !== undefined) { ts.bold = style.bold; f.push('bold'); }
      if (style.italic   !== undefined) { ts.italic = style.italic; f.push('italic'); }
      if (style.fontSize !== undefined) { ts.fontSize = { magnitude: style.fontSize, unit: 'PT' }; f.push('fontSize'); }
      if (style.foregroundColor) { ts.foregroundColor = style.foregroundColor; f.push('foregroundColor'); }
      if (f.length) fmt.push({ updateTextStyle: {
        range: { startIndex: start, endIndex: se }, textStyle: ts, fields: f.join(',') } });
    }
  }
  if (align) fmt.push({ updateParagraphStyle: {
    range: { startIndex: start, endIndex: end },
    paragraphStyle: { alignment: align }, fields: 'alignment' } });
}
const header = t => add(t + '\n', { bold: true, fontSize: 12, foregroundColor: DARK_BLUE });

const money = n => (typeof n === 'number' ? '$' + n.toLocaleString() : null);
const sal = d.salary_min || d.salary_max
  ? [money(d.salary_min), money(d.salary_max)].filter(Boolean).join(' - ') : null;

add('INTERVIEW PREP\n', { bold: true, fontSize: 18 }, 'CENTER');
add(d.title + '  —  ' + d.company + '\n', { fontSize: 12 }, 'CENTER');
const meta = [
  d.role_type || null,
  d.location || null,
  sal,
  typeof d.score === 'number' ? 'Fit score ' + d.score + '%' : null,
].filter(Boolean).join('  •  ');
if (meta) add(meta + '\n', { fontSize: 9, italic: true, foregroundColor: MED_GRAY }, 'CENTER');
add('\n');

if (r.role_snapshot) {
  header('THE ROLE');
  add(r.role_snapshot + '\n\n', { fontSize: 10 });
}

function section(titleText, items, note) {
  if (!Array.isArray(items) || !items.length) return;
  header(titleText);
  if (note) add(note + '\n', { fontSize: 9, italic: true, foregroundColor: MED_GRAY });
  items.forEach((q, i) => {
    add((i + 1) + '.  ' + (q.question || '') + '\n', { bold: true, fontSize: 10 });
    if (q.why)         add('     Why: ' + q.why + '\n', { fontSize: 9, italic: true, foregroundColor: MED_GRAY });
    if (q.answer_with) add('     Answer with: ' + q.answer_with + '\n', { fontSize: 10 });
    add('\n');
  });
}

section('REQUIRED SKILLS — EXPECT THESE', r.required_tech);
section('NICE-TO-HAVES — WHERE THE JOB IS WON', r.nice_to_haves,
        'Preferred/bonus items from the posting. Fewer candidates prepare for these.');
section('YOUR GAPS — ANSWER HONESTLY', r.gap_questions,
        'Do not bluff. Lead with the adjacent experience, then what you are learning.');

if (Array.isArray(r.ask_them) && r.ask_them.length) {
  header('QUESTIONS TO ASK THEM');
  r.ask_them.forEach(q => add('  •  ' + q + '\n', { fontSize: 10 }));
  add('\n');
}

add('\n');
add('Generated ' + new Date().toISOString().split('T')[0] +
    ' from the job description on file. Verify against the live posting before the call.\n',
    { fontSize: 8, italic: true, foregroundColor: MED_GRAY });

const counts = {
  required: (r.required_tech || []).length,
  nice: (r.nice_to_haves || []).length,
  gaps: (r.gap_questions || []).length,
  ask: (r.ask_them || []).length,
};

return [{ json: {
  page_id: d.page_id, ok: true,
  doc_title: d.doc_title,
  folder_id: d.folder_id,
  counts,
  doc_batch_body: JSON.stringify({
    requests: [{ insertText: { location: { index: 1 }, text } }, ...fmt] }),
  title: d.title, company: d.company, page_url: d.page_url,
}}];

// Assemble the Notion patch and the Discord message now that the doc exists.
// Pre-built as strings so the HTTP nodes carry no complex inline expressions.
const p   = $('Parse Interview Sheet').first().json;
const doc = $('Create Prep Doc').first().json;

const docUrl = 'https://docs.google.com/document/d/' + doc.documentId + '/edit';
const c = p.counts || {};

const discordMsg = [
  '🎤 **Interview prep ready!**',
  '**' + p.title + '** @ ' + p.company,
  `${c.required || 0} required-skill questions • ${c.nice || 0} nice-to-have • ` +
  `${c.gaps || 0} gap • ${c.ask || 0} to ask them`,
  '',
  '📝 [Interview Prep Sheet](' + docUrl + ')',
  p.page_url || '',
].filter(Boolean).join('\n');

return [{ json: {
  page_id: p.page_id,
  doc_url: docUrl,
  discord_msg: discordMsg,
  notion_patch: JSON.stringify({
    properties: { 'Interview Prep': { url: docUrl } },
  }),
}}];

// Release the lock so clearing the Interview Prep cell can regenerate later.
const state  = $getWorkflowStaticData('global');
const pageId = $('Pick One Interview').first().json.id;
const locks  = state.prepping || {};
delete locks[pageId];
state.prepping = locks;
return [{ json: { cleared: pageId } }];

// Token spend for the prep call, mirroring the other two workflows.
const resp = $input.first().json;
const u = resp.usage || {};
const model = resp.model || 'unknown';
const i = u.input_tokens || 0, o = u.output_tokens || 0;
const cr = u.cache_read_input_tokens || 0, cw = u.cache_creation_input_tokens || 0;

let inCpm, outCpm;
if      (model.includes('haiku'))    { inCpm =  1.00; outCpm =  5.00; }
else if (model.includes('sonnet-5')) { inCpm =  2.00; outCpm = 10.00; }
else if (model.includes('sonnet'))   { inCpm =  3.00; outCpm = 15.00; }
else if (model.includes('opus'))     { inCpm =  5.00; outCpm = 25.00; }
else if (model.includes('fable'))    { inCpm = 10.00; outCpm = 50.00; }
else                                 { inCpm =  1.00; outCpm =  5.00; }

const micro = Math.round(i * inCpm + o * outCpm + cr * inCpm * 0.10);
const esc = s => String(s).replace(/[ ,=]/g, '\\$&');
const line = `ai_cost,workflow=${esc('job-interview-prep')},model=${esc(model)} ` +
  `input_tokens=${i}i,output_tokens=${o}i,cache_read_tokens=${cr}i,` +
  `cache_write_tokens=${cw}i,cost_microdollars=${micro}i ${Date.now() * 1000000}`;
return [{ json: { line, model, micro } }];
